import { NextResponse } from 'next/server'

const SPEC = {
  openapi: '3.0.3',
  info: {
    title: 'errornote.ai LMS API',
    description:
      'REST API for Canvas/Moodle LMS integration with errornote.ai. ' +
      'All `/api/lms/*` endpoints require `Authorization: Bearer <api-key>`. ' +
      'API keys are generated by professors at `/settings/api-keys`.',
    version: '1.0.0',
    contact: { email: 'support@errornote.ai' },
  },
  servers: [{ url: '', description: 'Current host' }],
  security: [{ bearerAuth: [] }],
  components: {
    securitySchemes: {
      bearerAuth: {
        type: 'http',
        scheme: 'bearer',
        bearerFormat: 'hex64',
        description: 'API key generated by the professor in the errornote.ai settings page.',
      },
      cookieAuth: {
        type: 'apiKey',
        in: 'cookie',
        name: 'sb-access-token',
        description:
          'Supabase professor session cookie. Used by session-authenticated management endpoints (API keys, LTI platform registration).',
      },
    },
    schemas: {
      Error: {
        type: 'object',
        properties: { error: { type: 'string' } },
        required: ['error'],
      },
      LMSClass: {
        type: 'object',
        properties: {
          id: { type: 'string', format: 'uuid' },
          name: { type: 'string' },
          semester: { type: 'string', example: '2026-1' },
          invite_code: { type: 'string' },
          is_active: { type: 'boolean' },
          student_count: { type: 'integer' },
          created_at: { type: 'string', format: 'date-time' },
        },
        required: ['id', 'name', 'semester', 'invite_code', 'is_active', 'student_count', 'created_at'],
      },
      LMSStudent: {
        type: 'object',
        properties: {
          id: { type: 'string', format: 'uuid', description: 'Supabase auth user ID' },
          name: { type: 'string', nullable: true },
          student_id: { type: 'string', nullable: true, description: 'University student number' },
          email: { type: 'string', format: 'email', nullable: true },
          enrolled_at: { type: 'string', format: 'date-time' },
        },
        required: ['id', 'enrolled_at'],
      },
      LMSAssignment: {
        type: 'object',
        properties: {
          id: { type: 'string', format: 'uuid' },
          title: { type: 'string' },
          prompt_text: { type: 'string' },
          due_date: { type: 'string', format: 'date-time', nullable: true },
          created_at: { type: 'string', format: 'date-time' },
        },
        required: ['id', 'title', 'prompt_text', 'created_at'],
      },
      LMSGradeEntry: {
        type: 'object',
        properties: {
          student_id: { type: 'string', format: 'uuid' },
          student_name: { type: 'string', nullable: true },
          student_number: { type: 'string', nullable: true },
          assignment_id: { type: 'string', format: 'uuid' },
          assignment_title: { type: 'string' },
          session_id: { type: 'string', format: 'uuid', nullable: true },
          draft_error_count: { type: 'integer', nullable: true },
          revision_error_count: { type: 'integer', nullable: true },
          improvement: {
            type: 'integer',
            nullable: true,
            description: 'draft_error_count − revision_error_count; positive = improvement',
          },
          submitted_at: { type: 'string', format: 'date-time', nullable: true },
        },
        required: ['student_id', 'assignment_id'],
      },
      LMSApiKeyRecord: {
        type: 'object',
        properties: {
          id: { type: 'string', format: 'uuid' },
          name: { type: 'string' },
          key_prefix: { type: 'string', description: 'First 8 chars of hash + "…" (never the raw key)' },
          scopes: { type: 'array', items: { type: 'string' } },
          last_used_at: { type: 'string', format: 'date-time', nullable: true },
          created_at: { type: 'string', format: 'date-time' },
          is_active: { type: 'boolean' },
        },
        required: ['id', 'name', 'key_prefix', 'scopes', 'created_at', 'is_active'],
      },
      LtiPlatform: {
        type: 'object',
        description: 'A registered LTI 1.3 platform (Canvas / Moodle issuer).',
        properties: {
          id: { type: 'string', format: 'uuid' },
          name: { type: 'string', example: 'Canvas (prod)' },
          issuer: { type: 'string', description: 'Platform `iss`', example: 'https://canvas.instructure.com' },
          client_id: { type: 'string', description: 'Tool client_id issued by the platform' },
          deployment_id: { type: 'string', nullable: true },
          auth_login_url: { type: 'string', format: 'uri', description: 'Platform OIDC auth endpoint' },
          auth_token_url: { type: 'string', format: 'uri', description: 'Platform OAuth2 token endpoint (AGS/NRPS)' },
          jwks_uri: { type: 'string', format: 'uri', description: "Platform public JWKS used to verify id_token" },
          class_id: {
            type: 'string',
            format: 'uuid',
            nullable: true,
            description: 'Optional pre-bound errornote class; otherwise resolved from the LTI context claim',
          },
          created_at: { type: 'string', format: 'date-time' },
        },
        required: ['id', 'name', 'issuer', 'client_id', 'auth_login_url', 'auth_token_url', 'jwks_uri', 'created_at'],
      },
      LtiPlatformInput: {
        type: 'object',
        properties: {
          name: { type: 'string', example: 'Canvas (prod)' },
          issuer: { type: 'string', example: 'https://canvas.instructure.com' },
          clientId: { type: 'string' },
          deploymentId: { type: 'string', nullable: true },
          authLoginUrl: { type: 'string', format: 'uri' },
          authTokenUrl: { type: 'string', format: 'uri' },
          jwksUri: { type: 'string', format: 'uri' },
          classId: { type: 'string', format: 'uuid', nullable: true },
        },
        required: ['name', 'issuer', 'clientId', 'authLoginUrl', 'authTokenUrl', 'jwksUri'],
      },
      Jwks: {
        type: 'object',
        description: 'JSON Web Key Set (RFC 7517). Empty `keys` when the tool signing key is not configured.',
        properties: {
          keys: { type: 'array', items: { type: 'object', additionalProperties: true } },
        },
        required: ['keys'],
      },
    },
    parameters: {
      classId: {
        name: 'classId',
        in: 'path',
        required: true,
        schema: { type: 'string', format: 'uuid' },
        description: 'Class UUID',
      },
    },
    responses: {
      Unauthorized: {
        description: 'Missing or invalid API key, or rate limit exceeded (100 req/min)',
        content: { 'application/json': { schema: { $ref: '#/components/schemas/Error' } } },
      },
      NotFound: {
        description: 'Resource not found or not owned by this professor',
        content: { 'application/json': { schema: { $ref: '#/components/schemas/Error' } } },
      },
    },
  },
  paths: {
    '/api/lms/classes': {
      get: {
        summary: "List professor's classes",
        description: 'Returns all classes owned by the professor associated with the API key.',
        operationId: 'listClasses',
        tags: ['Classes'],
        responses: {
          '200': {
            description: 'OK',
            content: {
              'application/json': {
                schema: {
                  type: 'object',
                  properties: {
                    classes: { type: 'array', items: { $ref: '#/components/schemas/LMSClass' } },
                  },
                },
              },
            },
          },
          '401': { $ref: '#/components/responses/Unauthorized' },
        },
      },
    },
    '/api/lms/classes/{classId}/students': {
      get: {
        summary: 'Get class roster',
        operationId: 'listStudents',
        tags: ['Classes'],
        parameters: [{ $ref: '#/components/parameters/classId' }],
        responses: {
          '200': {
            description: 'OK',
            content: {
              'application/json': {
                schema: {
                  type: 'object',
                  properties: {
                    students: { type: 'array', items: { $ref: '#/components/schemas/LMSStudent' } },
                  },
                },
              },
            },
          },
          '401': { $ref: '#/components/responses/Unauthorized' },
          '404': { $ref: '#/components/responses/NotFound' },
        },
      },
    },
    '/api/lms/classes/{classId}/assignments': {
      get: {
        summary: 'List assignments for a class',
        operationId: 'listAssignments',
        tags: ['Classes'],
        parameters: [{ $ref: '#/components/parameters/classId' }],
        responses: {
          '200': {
            description: 'OK',
            content: {
              'application/json': {
                schema: {
                  type: 'object',
                  properties: {
                    assignments: { type: 'array', items: { $ref: '#/components/schemas/LMSAssignment' } },
                  },
                },
              },
            },
          },
          '401': { $ref: '#/components/responses/Unauthorized' },
          '404': { $ref: '#/components/responses/NotFound' },
        },
      },
    },
    '/api/lms/classes/{classId}/grades': {
      get: {
        summary: 'Export grades for a class',
        description:
          'Returns per-student, per-assignment error counts and improvement scores. ' +
          'Optionally filter by `assignmentId`.',
        operationId: 'listGrades',
        tags: ['Classes'],
        parameters: [
          { $ref: '#/components/parameters/classId' },
          {
            name: 'assignmentId',
            in: 'query',
            required: false,
            schema: { type: 'string', format: 'uuid' },
            description: 'Filter to a single assignment',
          },
        ],
        responses: {
          '200': {
            description: 'OK',
            content: {
              'application/json': {
                schema: {
                  type: 'object',
                  properties: {
                    grades: { type: 'array', items: { $ref: '#/components/schemas/LMSGradeEntry' } },
                  },
                },
              },
            },
          },
          '401': { $ref: '#/components/responses/Unauthorized' },
          '404': { $ref: '#/components/responses/NotFound' },
        },
      },
    },
    '/api/lms/keys': {
      get: {
        summary: "List professor's API keys",
        description:
          'Session-authenticated (cookie). Returns metadata only — raw keys are never re-exposed.',
        operationId: 'listApiKeys',
        tags: ['API Keys'],
        security: [{ cookieAuth: [] }],
        responses: {
          '200': {
            description: 'OK',
            content: {
              'application/json': {
                schema: {
                  type: 'object',
                  properties: {
                    keys: { type: 'array', items: { $ref: '#/components/schemas/LMSApiKeyRecord' } },
                  },
                },
              },
            },
          },
          '401': { $ref: '#/components/responses/Unauthorized' },
        },
      },
      post: {
        summary: 'Create a new API key',
        description:
          'Session-authenticated. Returns the raw key **once** — store it securely. ' +
          'Subsequent calls only reveal the key prefix.',
        operationId: 'createApiKey',
        tags: ['API Keys'],
        security: [{ cookieAuth: [] }],
        requestBody: {
          required: true,
          content: {
            'application/json': {
              schema: {
                type: 'object',
                properties: {
                  name: { type: 'string', example: 'Canvas prod' },
                  scopes: {
                    type: 'array',
                    items: { type: 'string', enum: ['classes', 'students', 'assignments', 'grades'] },
                    example: ['classes', 'grades'],
                  },
                },
                required: ['name'],
              },
            },
          },
        },
        responses: {
          '201': {
            description: 'Key created',
            content: {
              'application/json': {
                schema: {
                  type: 'object',
                  properties: {
                    key: { type: 'string', description: 'Raw 64-char hex key — shown once only' },
                    record: { $ref: '#/components/schemas/LMSApiKeyRecord' },
                  },
                },
              },
            },
          },
          '400': {
            description: 'Validation error',
            content: { 'application/json': { schema: { $ref: '#/components/schemas/Error' } } },
          },
          '401': { $ref: '#/components/responses/Unauthorized' },
        },
      },
      delete: {
        summary: 'Revoke an API key',
        description: 'Session-authenticated. Marks the key inactive; it will immediately stop working.',
        operationId: 'revokeApiKey',
        tags: ['API Keys'],
        security: [{ cookieAuth: [] }],
        parameters: [
          {
            name: 'id',
            in: 'query',
            required: true,
            schema: { type: 'string', format: 'uuid' },
            description: 'API key ID to revoke',
          },
        ],
        responses: {
          '200': {
            description: 'Revoked',
            content: {
              'application/json': {
                schema: { type: 'object', properties: { success: { type: 'boolean' } } },
              },
            },
          },
          '401': { $ref: '#/components/responses/Unauthorized' },
        },
      },
    },
    '/api/lti/login': {
      get: {
        summary: 'LTI 1.3 OIDC third-party login initiation',
        description:
          'Platform-initiated (no API key). Resolves the registered platform by `iss` (+ optional `client_id`), ' +
          'persists a one-time `state`/`nonce`, and 302-redirects to the platform authentication endpoint. ' +
          'Also accepts POST (form-encoded) with the same parameters.',
        operationId: 'ltiLogin',
        tags: ['LTI 1.3'],
        security: [],
        parameters: [
          { name: 'iss', in: 'query', required: true, schema: { type: 'string' }, description: 'Platform issuer' },
          { name: 'login_hint', in: 'query', required: true, schema: { type: 'string' } },
          { name: 'target_link_uri', in: 'query', required: true, schema: { type: 'string', format: 'uri' } },
          { name: 'lti_message_hint', in: 'query', required: false, schema: { type: 'string' } },
          { name: 'client_id', in: 'query', required: false, schema: { type: 'string' } },
        ],
        responses: {
          '302': { description: 'Redirect to the platform authentication request' },
          '400': {
            description: 'Missing iss / login_hint / target_link_uri',
            content: { 'application/json': { schema: { $ref: '#/components/schemas/Error' } } },
          },
          '404': {
            description: 'Unknown LTI platform',
            content: { 'application/json': { schema: { $ref: '#/components/schemas/Error' } } },
          },
        },
      },
      post: {
        summary: 'LTI 1.3 OIDC login initiation (form_post)',
        operationId: 'ltiLoginPost',
        tags: ['LTI 1.3'],
        security: [],
        requestBody: {
          required: true,
          content: {
            'application/x-www-form-urlencoded': {
              schema: {
                type: 'object',
                properties: {
                  iss: { type: 'string' },
                  login_hint: { type: 'string' },
                  target_link_uri: { type: 'string' },
                  lti_message_hint: { type: 'string' },
                  client_id: { type: 'string' },
                },
                required: ['iss', 'login_hint', 'target_link_uri'],
              },
            },
          },
        },
        responses: {
          '302': { description: 'Redirect to the platform authentication request' },
          '400': { description: 'Missing required parameter' },
          '404': { description: 'Unknown LTI platform' },
        },
      },
    },
    '/api/lti/launch': {
      post: {
        summary: 'LTI 1.3 resource link / deep-linking launch',
        description:
          'Platform-initiated `form_post` carrying `id_token` + `state`. The tool consumes the one-time state, ' +
          'verifies the id_token signature against the platform JWKS (iss/aud/exp/nonce + required LTI claims), ' +
          'provisions/maps the user, links the LTI context to a class, then 302-redirects into the app via a magic link. ' +
          'For a `LtiDeepLinkingRequest`, returns a chapter-selection HTML page instead.',
        operationId: 'ltiLaunch',
        tags: ['LTI 1.3'],
        security: [],
        requestBody: {
          required: true,
          content: {
            'application/x-www-form-urlencoded': {
              schema: {
                type: 'object',
                properties: { id_token: { type: 'string' }, state: { type: 'string' } },
                required: ['id_token', 'state'],
              },
            },
          },
        },
        responses: {
          '200': {
            description: 'Deep Linking content-selection page (HTML)',
            content: { 'text/html': { schema: { type: 'string' } } },
          },
          '302': { description: 'Redirect into the app (resource link launch)' },
          '400': { description: 'Missing id_token/state, invalid/expired state, or missing deep_linking_settings' },
          '401': { description: 'id_token verification or LTI claim validation failed' },
          '404': { description: 'Unknown LTI platform' },
        },
      },
    },
    '/api/lti/jwks': {
      get: {
        summary: 'Tool public JWKS',
        description:
          'Public JSON Web Key Set the platform uses to verify tool-signed messages (Deep Linking / AGS responses). ' +
          'Returns an empty key set when the tool signing key is not configured.',
        operationId: 'ltiJwks',
        tags: ['LTI 1.3'],
        security: [],
        responses: {
          '200': {
            description: 'OK',
            content: { 'application/json': { schema: { $ref: '#/components/schemas/Jwks' } } },
          },
        },
      },
    },
    '/api/lti/deep-link/respond': {
      post: {
        summary: 'Deep Linking response (content-item selection)',
        description:
          'Receives the chapter selection from the launch page. Verifies the HMAC handoff token, builds an ' +
          '`ltiResourceLink` content item, signs an `LtiDeepLinkingResponse` JWT, and returns an auto-POST HTML ' +
          'form targeting the platform `deep_link_return_url`. Secured by the signed handoff token, not an API key.',
        operationId: 'ltiDeepLinkRespond',
        tags: ['LTI 1.3'],
        security: [],
        requestBody: {
          required: true,
          content: {
            'application/x-www-form-urlencoded': {
              schema: {
                type: 'object',
                properties: {
                  token: { type: 'string', description: 'HMAC handoff token minted at launch' },
                  chapter: { type: 'integer', description: 'Selected chapter number' },
                },
                required: ['token', 'chapter'],
              },
            },
          },
        },
        responses: {
          '200': {
            description: 'Auto-POST form to deep_link_return_url (HTML)',
            content: { 'text/html': { schema: { type: 'string' } } },
          },
          '400': { description: 'Invalid chapter or expired/invalid handoff token (HTML)' },
          '500': { description: 'Deep Linking response signing failed (HTML)' },
        },
      },
    },
    '/api/lti/platforms': {
      get: {
        summary: 'List registered LTI platforms',
        description: 'Session-authenticated. Returns the platforms registered by the current professor.',
        operationId: 'listLtiPlatforms',
        tags: ['LTI 1.3'],
        security: [{ cookieAuth: [] }],
        responses: {
          '200': {
            description: 'OK',
            content: {
              'application/json': {
                schema: {
                  type: 'object',
                  properties: {
                    platforms: { type: 'array', items: { $ref: '#/components/schemas/LtiPlatform' } },
                  },
                },
              },
            },
          },
          '401': { $ref: '#/components/responses/Unauthorized' },
        },
      },
      post: {
        summary: 'Register an LTI platform',
        description: 'Session-authenticated. Registers a Canvas/Moodle platform for the current professor.',
        operationId: 'createLtiPlatform',
        tags: ['LTI 1.3'],
        security: [{ cookieAuth: [] }],
        requestBody: {
          required: true,
          content: {
            'application/json': { schema: { $ref: '#/components/schemas/LtiPlatformInput' } },
          },
        },
        responses: {
          '201': {
            description: 'Platform registered',
            content: {
              'application/json': {
                schema: {
                  type: 'object',
                  properties: { platform: { $ref: '#/components/schemas/LtiPlatform' } },
                },
              },
            },
          },
          '400': {
            description: 'Validation error',
            content: { 'application/json': { schema: { $ref: '#/components/schemas/Error' } } },
          },
          '401': { $ref: '#/components/responses/Unauthorized' },
          '409': {
            description: 'Duplicate platform (issuer/client_id/deployment already registered)',
            content: { 'application/json': { schema: { $ref: '#/components/schemas/Error' } } },
          },
        },
      },
    },
    '/api/lti/platforms/{id}': {
      delete: {
        summary: 'Delete a registered LTI platform',
        description: 'Session-authenticated. Deletes a platform owned by the current professor.',
        operationId: 'deleteLtiPlatform',
        tags: ['LTI 1.3'],
        security: [{ cookieAuth: [] }],
        parameters: [
          {
            name: 'id',
            in: 'path',
            required: true,
            schema: { type: 'string', format: 'uuid' },
            description: 'Platform ID',
          },
        ],
        responses: {
          '200': {
            description: 'Deleted',
            content: {
              'application/json': {
                schema: { type: 'object', properties: { success: { type: 'boolean' } } },
              },
            },
          },
          '400': {
            description: 'Invalid id',
            content: { 'application/json': { schema: { $ref: '#/components/schemas/Error' } } },
          },
          '401': { $ref: '#/components/responses/Unauthorized' },
        },
      },
    },
  },
  tags: [
    { name: 'Classes', description: 'LMS data endpoints — secured by API key' },
    { name: 'API Keys', description: 'Key management — secured by professor session cookie' },
    {
      name: 'LTI 1.3',
      description:
        'LTI 1.3 Advantage adapter (Canvas/Moodle): OIDC login, resource-link & deep-linking launch, tool JWKS, ' +
        'and professor-facing platform registration. Launch/login/jwks/deep-link are secured by the LTI protocol ' +
        '(signed id_token, one-time state, HMAC handoff token), not by API keys.',
    },
  ],
}

export async function GET() {
  return NextResponse.json(SPEC, {
    headers: { 'Cache-Control': 'public, max-age=3600' },
  })
}
